import{_ as n,o as a,c as i,ae as t}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"ADR-001: Pure OpenClaw Plugin, No CLI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adrs/001.md","filePath":"reference/adrs/001.md"}'),o={name:"reference/adrs/001.md"};function s(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-001-pure-openclaw-plugin-no-cli" tabindex="-1">ADR-001: Pure OpenClaw Plugin, No CLI <a class="header-anchor" href="#adr-001-pure-openclaw-plugin-no-cli" aria-label="Permalink to &quot;ADR-001: Pure OpenClaw Plugin, No CLI&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The reference project oh-my-codex ships a standalone CLI binary (<code>omx</code>) with 20+ subcommands, plus 4 Rust native crates for file exploration, shell detection, and runtime management. This architecture suits a project that runs independently alongside a host CLI.</p><p>omm targets the OpenClaw Gateway（OpenClaw 网关）, which loads plugins directly via a <code>register(api)</code> entry point and dispatches tool calls and skill execution through its own runtime. In this environment, a standalone binary would be redundant — all functionality is accessed through the Gateway&#39;s plugin and skill mechanisms.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>omm is a pure OpenClaw plugin with no standalone binary and no Rust native modules.</p><ul><li>All tools are registered via <code>api.registerTool()</code> in the plugin entry point</li><li>All skills are defined as SKILL.md files interpreted by the Gateway&#39;s skill runtime</li><li>The MCP server runs as a separate stdio process but is not a user-facing CLI</li><li>Distribution is a single JS-only tarball (<code>omm-suite-&lt;version&gt;.tgz</code>)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Simpler build: TypeScript only, no Rust toolchain, no cross-compilation</li><li>Smaller distribution: single tarball vs npm binary + native addons</li><li>Fewer moving parts: no process management, no PATH configuration</li><li>Natural fit: the Gateway already provides tool dispatch and skill execution</li></ul><p><strong>Negative:</strong></p><ul><li>No independent testability outside an OpenClaw environment — integration testing requires a Gateway or mock</li><li>No standalone CLI for ad-hoc debugging — must use MCP server or plugin test harness</li><li>Dependent on OpenClaw Plugin ABI stability — ABI changes require omm updates</li></ul><p><strong>Trade-off accepted:</strong> omm sacrifices standalone operation for tighter Gateway integration and simpler distribution. This is appropriate because omm&#39;s value proposition is extending an existing OpenClaw environment, not running independently.</p>',13)])])}const m=n(o,[["render",s]]);export{h as __pageData,m as default};
